# librariesimport pandas as pdimport numpy as npfrom sklearn.metrics import mutual_info_scorefrom collections import Counterfrom tqdm import tqdmfrom scipy.io import mmread ### define functionsdef mutualInfo(binarized_data, cluster_labels, gene_labels):    """    Parameters    ----------    binarized_data : TYPE data frame        DESCRIPTION. binarized gene expression matrix where        rows are genes and columns are cells            cluster_labels : TYPE series        DESCRIPTION.        labels for each cell, should be same dimension as binarized data        columns            gene_labels : TYPE series        DESCRIPTION.        labels for each gene, which is otherwise referred to as a row index            Returns    -------    mutual_info : TYPE        DESCRIPTION. data frame with columns for mutual info, gene, and gene        index    """    print('mutualInfo')    results = []    for gene_index, row in tqdm(binarized_data.iterrows()):        mi = mutual_info_score(row, cluster_labels) / np.log(2)  # Convert from nats to bits        results.append({            'MI': mi,            'gene': gene_labels[gene_index],            'gene_index': gene_index        })    mutual_info = pd.DataFrame(results)    return mutual_infodef totalInfo(binarized_data, cluster_labels, gene_indices, gene_labels):    """    Parameters    ----------      binarized_data : TYPE data frame      DESCRIPTION. binarized gene expression matrix where      rows are genes and columns are cells            cluster_labels : TYPE DataFrame      DESCRIPTION.      labels for each cell, should be same dimension as binarized data      columns            gene_indices : TYPE        DESCRIPTION.        index for each gene            gene_labels : TYPE series        DESCRIPTION.        labels for each gene, which is otherwise referred to as a row index        Returns    -------    I : TYPE float        DESCRIPTION.        total info in the dataset?    """    from scipy.stats import entropy    import numpy as np    print('totalInfo')        # Entropy of cluster labels alone    naive_entropy = entropy(cluster_labels['label'].value_counts(normalize=True), base=2)        # GEX with selected genes    df_temp = binarized_data.loc[gene_indices].T         H = 0  # Initialize conditional entropy accumulator        # Unique combinations of expression levels    for _, row in tqdm(df_temp.drop_duplicates().iterrows()):        # Get cell names having this unique combination of expression levels        cell_names = df_temp.index[np.all(df_temp == row, axis=1)]                # Get labels for cells with this expression pattern        labels_cond = cluster_labels.loc[cell_names, 'label']                # Calculate entropy of classification (conditional on expression levels)        H_cond = entropy(labels_cond.value_counts(normalize=True), base=2)                # Weight by fraction of cells in this set        weight = len(cell_names) / df_temp.shape[0]         H += H_cond * weight            # Information gain = naive entropy - conditional entropy    I = naive_entropy - H    return I#calculate total information from each gene set defined by iteratively adding a single genedef calcCumInfo(binarized_data, cluster_labels, genes, N=5):    print('calcCumInfo')        cis = []    for i in tqdm(range(0, N)):        print(i)        mi_cum = totalInfo(binarized_data, cluster_labels, binarized_data.index[:i+1], genes[:i+1])        cis.append(mi_cum)    cis = np.array(cis)    df_result = pd.DataFrame()    df_result["gene"] = genes[:N]    df_result.set_index("gene", inplace=True)    df_result["cumulative_mutual_information"] = cis    return df_resultdef findNonRedundantGeneSet(binarized_data,                            cluster_labels,                            mi_info,                            H_naive,                            N_constrain=20,                            cumulative_information_cutoff=0.99,                            verbose=True):    print('findNonRedundantGeneSet')    cis = []    nonredundant_genes = []    current_ci = 0    current_relative_ci = 0.0        # Use mi_info directly since it has gene names in 'gene' column    # Sort by MI and take top N_constrain genes    top_genes = mi_info.nlargest(N_constrain, 'MI')    remaining_genes = list(top_genes['gene'].values)        i = 0    while True:         i += 1                # Calculate info gain for each gene        df_info_gains = pd.DataFrame(index=list(remaining_genes))        my_info_gains = []                for gene in tqdm(remaining_genes):            my_genes = nonredundant_genes + [gene]            # Get indices directly from gene names            my_indices = [binarized_data.index[binarized_data.index == g][0] for g in my_genes]                        my_ci = totalInfo(binarized_data, cluster_labels, my_indices, my_genes)            my_info_gain = my_ci - current_ci            my_info_gains.append(my_info_gain)                df_info_gains["info_gain"] = my_info_gains                # Sort genes by info gain        df_info_gains.sort_values('info_gain', ascending=False, inplace=True)                # Take the best gene        hit = df_info_gains.index[0]                nonredundant_genes.append(hit)        remaining_genes.remove(hit)        current_ci = current_ci + df_info_gains.iloc[0]['info_gain']        current_relative_ci = current_ci / H_naive                if verbose:            print(hit)            print(current_relative_ci)            print()                if len(remaining_genes) == 0 or current_relative_ci > cumulative_information_cutoff:            return nonredundant_genesdef calcMeanClustExp(normalized_expression,                     cluster_labels,                     summary_func='mean'):    print('calcMeanClustExp')    import copy    df_temp = copy.deepcopy(normalized_expression.T).reset_index()    df_temp['cluster'] = cluster_labels['label'].values    df_summary_by_label = df_temp.groupby("cluster").agg(summary_func, numeric_only=True).T    del df_temp    return df_summary_by_labeldef head_threshold(df, threshold, field="relative_cumulative_information"):    print('head_threshold')    L = max(np.where(df[field] <= threshold)[0]) + 2    print(L)    return df.iloc[:L]###----##### read in dataexpression_matrix = mmread("/Users/ggraham/MERFISH/2025_10_06_genes_meeting_criteria.mtx")""" here, rows are genes (unlabeled) and columns are cells,all of the genes listed here are marker genes that fit Duncans criteriato save computation"""expression_matrix = pd.DataFrame(expression_matrix.toarray())genes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes = genes['x']"""genes corresponds to the genes in expression matrix"""clusters = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_clusters.csv")"""clusters['clusters'] corresponds to the cluster label for each cell"""# Set up data structure like the originalexpression_binary = (expression_matrix > 0).astype(int)expression_binary.index = genes  # Set gene names as index# Create labels dataframe - make sure cell names match expression matrix columnscell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)# Debug: check that everything alignsprint("Data alignment check:")print(f"Expression matrix shape: {expression_binary.shape}")print(f"Number of cells in expression matrix: {expression_binary.shape[1]}")print(f"Number of cluster labels: {len(clusters['clusters'])}")print(f"df_labels shape: {df_labels.shape}")print(f"Unique clusters: {df_labels['label'].nunique()}")print(f"Do indices match? {all(expression_binary.columns == df_labels.index)}")print(f"Sample cluster distribution:")print(df_labels['label'].value_counts().head())clusters.tail()expression_binary.tail()expression_matrix.iloc[-1, :].max()##### ok now the real deal ######## train classifier # Use the original calc_mutual_information function approachdef calc_mutual_information(df_discrete, labels):    mutual_informations = []    for symbol, row in df_discrete.iterrows():        mi = mutual_info_score(row, labels) / np.log(2)  # calculate mutual information, convert from nats to bits        mutual_informations.append(mi)    df_result = pd.DataFrame()    df_result["symbol"] = df_discrete.index    df_result.set_index("symbol", inplace=True)    df_result["mutual_information"] = mutual_informations    df_result.sort_values("mutual_information", inplace=True, ascending=False)    return df_result#compute mutual info using original functiondf_info = calc_mutual_information(expression_binary, df_labels["label"])#compute mean expression for each gene within each cluster# Fixed: removed the iloc[0:,1:] slicingdf_expr_labels = calcMeanClustExp(expression_matrix, df_labels)#calculate relative cum info#total entropyfrom scipy.stats import entropy H_naive = entropy(df_labels['label'].value_counts(normalize=True), base=2)print("Total entropy of classification", H_naive, "bits")# Use original find_nonredundant_gene_set functiondef find_nonredundant_gene_set(df_discrete, genes,                               df_labels,                               df_info,                               H_naive,                               N_constrain=20,                               cumulative_information_cutoff=0.99,                               verbose=False):    print('find_nonredundant_gene_set')    cis = []    nonredundant_genes = []    current_ci = 0    current_relative_ci = 0.0        # Rank genes by mutual information    remaining_genes = list(df_info.loc[genes]["mutual_information"].sort_values(ascending=False).head(n=N_constrain).index)        i = 0        while True:                i += 1                # Calculate information gain for each gene        df_info_gains = pd.DataFrame(index=list(remaining_genes))        my_info_gains = []                for gene in tqdm(remaining_genes):            my_genes = nonredundant_genes + [gene]            # Use original calc_cumulative_information_of_set function            my_ci = calc_cumulative_information_of_set(df_discrete, my_genes, df_labels)            my_info_gain = my_ci - current_ci            my_info_gains.append(my_info_gain)                df_info_gains["info_gain"] = my_info_gains                # Sort genes by information gain        df_info_gains.sort_values("info_gain", ascending=False, inplace=True)                # Take best gene        hit = df_info_gains["info_gain"].index[0]                nonredundant_genes.append(hit)        remaining_genes.remove(hit)        current_ci = current_ci + df_info_gains.iloc[0]["info_gain"]        current_relative_ci = current_ci / H_naive                if verbose:            print(hit)            print(current_relative_ci)            print()                if len(remaining_genes) == 0 or current_relative_ci > cumulative_information_cutoff:            return nonredundant_genes# Use original calc_cumulative_information_of_set functiondef calc_cumulative_information_of_set(df_discrete, genes, df_labels):    """ Calculates total information of gene set """    print('calc_cumulative_information_of_set')    import scipy.stats    # Entropy of class without knowledge of genes    H_naive = scipy.stats.entropy(df_labels["label"].value_counts(normalize=True), base=2)    # Get discretized gene expression matrix with only selected genes    df_temp = df_discrete.loc[genes].T    H = 0    # Find unique combinations of expression levels    for _, row in tqdm(df_temp.drop_duplicates().iterrows()):        cell_names = df_temp.index[np.all(df_temp == row, axis=1)]  # Get cell names having this unique combination of expression levels        labels_cond = df_labels.loc[cell_names]["label"]  # Get class labels of cells        # Calculate entropy of classification (conditional on expression levels)        H_cond = scipy.stats.entropy(labels_cond.value_counts(normalize=True), base=2)        weight = len(cell_names) / df_temp.shape[0]  # Weight by fraction of cells in this set        H += H_cond * weight    I = H_naive - H    return I# Use original calc_cumulative_informations functiondef calc_cumulative_informations(df_discrete, genes, df_labels, N=5):    """ Calculates total information of gene sets starting from top of df """    print('calc_cumulative_informations')    cis = []    for i in tqdm(range(0, N)):        my_ci = calc_cumulative_information_of_set(df_discrete, genes[:i+1], df_labels)        cis.append(my_ci)    cis = np.array(cis)    df_result = pd.DataFrame()    df_result["symbol"] = genes    df_result.set_index("symbol", inplace=True)    df_result["cumulative_mutual_information"] = ""    df_result["cumulative_mutual_information"] = np.nan    df_result["cumulative_mutual_information"].loc[genes[:N]] = cis    return df_result#find non redundant gene set using original approachgenes_nonredundant = find_nonredundant_gene_set(    expression_binary,     df_info.head(n=100).index,  # Top 100 genes by MI    df_labels,     df_info,     H_naive,    N_constrain=100,    cumulative_information_cutoff=0.95,    verbose=True)print(genes_nonredundant)#calculate relative cum infodf_info_nonredundant = df_info.copy()#calculate cum info for top N genes using original approachcumulative_informations = calc_cumulative_informations(    expression_binary,     genes_nonredundant,    df_labels,     N=len(genes_nonredundant))df_info_nonredundant['cumulative_information'] = cumulative_informations['cumulative_mutual_information']#calculate information relative to total entropyrelative_cumulative_informations = df_info_nonredundant["cumulative_information"] / H_naivedf_info_nonredundant["relative_cumulative_information"] = relative_cumulative_informations#sort - Fixed: added ascending=False to get genes in order of importancedf_info_nonredundant.sort_values("relative_cumulative_information", inplace=True, ascending=False)#prunegenes_nonredundant_minimal = list(head_threshold(df_info_nonredundant, 0.95).index)# Peek at minimal setdf_info_nonredundant['symbol'] = df_info_nonredundant.indexminimal_set = df_info_nonredundant.head(len(genes_nonredundant_minimal))['symbol' if 'symbol' in df_info_nonredundant.columns                                                             else df_info_nonredundant.index.name]#minimal_set.to_csv('/Users/ggraham/MERFISH/10_06_2025_minimal_set_MI.csv')### validationdef validate_classification_accuracy(expression_binary, cluster_labels, gene_set, n_folds=5, random_state=42):    """    Test classification accuracy using cross-validation        Parameters:    -----------    expression_binary : DataFrame        Binarized gene expression matrix (genes as rows, cells as columns)    cluster_labels : Series or array        Cluster labels for each cell    gene_set : list        List of gene names to use for classification    n_folds : int        Number of cross-validation folds    random_state : int        Random seed for reproducibility            Returns:    --------    dict : Dictionary containing accuracy metrics    """    from sklearn.model_selection import cross_val_score, StratifiedKFold    from sklearn.ensemble import RandomForestClassifier    from sklearn.metrics import accuracy_score    import numpy as np        # Prepare data - transpose so cells are rows, genes are columns    X = expression_binary.loc[gene_set].T    y = cluster_labels        # Initialize classifier    clf = RandomForestClassifier(n_estimators=100, random_state=random_state)        # Perform cross-validation    cv = StratifiedKFold(n_splits=n_folds, shuffle=True, random_state=random_state)    cv_scores = cross_val_score(clf, X, y, cv=cv, scoring='accuracy')        # Calculate metrics    mean_accuracy = np.mean(cv_scores)    std_accuracy = np.std(cv_scores)        # Fit on full data to get feature importances    clf.fit(X, y)    feature_importance = dict(zip(gene_set, clf.feature_importances_))        results = {        'mean_cv_accuracy': mean_accuracy,        'std_cv_accuracy': std_accuracy,        'cv_scores': cv_scores,        'n_genes': len(gene_set),        'n_clusters': len(np.unique(y)),        'feature_importance': feature_importance    }        return results# Example usage:results = validate_classification_accuracy(expression_binary, clusters['clusters'], genes_nonredundant_minimal)# print(f"Mean CV Accuracy: {results['mean_cv_accuracy']:.3f} ± {results['std_cv_accuracy']:.3f}")print(f"Using {results['n_genes']} genes to classify {results['n_clusters']} clusters")def validate_confusion_matrix(expression_binary, cluster_labels, gene_set, random_state=42):    """    Analyze classification performance through confusion matrix        Parameters:    -----------    expression_binary : DataFrame        Binarized gene expression matrix (genes as rows, cells as columns)    cluster_labels : Series or array        Cluster labels for each cell    gene_set : list        List of gene names to use for classification    random_state : int        Random seed for reproducibility            Returns:    --------    dict : Dictionary containing confusion matrix metrics    """    from sklearn.model_selection import train_test_split    from sklearn.ensemble import RandomForestClassifier    from sklearn.metrics import confusion_matrix, classification_report    import numpy as np    import pandas as pd        # Prepare data    X = expression_binary.loc[gene_set].T    y = cluster_labels        # Split data    X_train, X_test, y_train, y_test = train_test_split(        X, y, test_size=0.3, random_state=random_state, stratify=y    )        # Train classifier    clf = RandomForestClassifier(n_estimators=100, random_state=random_state)    clf.fit(X_train, y_train)        # Make predictions    y_pred = clf.predict(X_test)        # Calculate confusion matrix    cm = confusion_matrix(y_test, y_pred)        # Get cluster names    cluster_names = sorted(np.unique(y))        # Convert to DataFrame for easier interpretation    cm_df = pd.DataFrame(cm, index=cluster_names, columns=cluster_names)        # Calculate per-cluster metrics    cluster_accuracies = {}    cluster_precisions = {}    cluster_recalls = {}        for i, cluster in enumerate(cluster_names):        # True positives for this cluster        tp = cm[i, i]        # False positives (other clusters predicted as this one)        fp = np.sum(cm[:, i]) - tp        # False negatives (this cluster predicted as others)        fn = np.sum(cm[i, :]) - tp                # Per-cluster accuracy (diagonal / row sum)        cluster_recall = tp / (tp + fn) if (tp + fn) > 0 else 0        cluster_precision = tp / (tp + fp) if (tp + fp) > 0 else 0                cluster_recalls[cluster] = cluster_recall        cluster_precisions[cluster] = cluster_precision        # Overall metrics    overall_accuracy = np.trace(cm) / np.sum(cm)    mean_cluster_recall = np.mean(list(cluster_recalls.values()))    mean_cluster_precision = np.mean(list(cluster_precisions.values()))        # Find most confused clusters    cm_off_diagonal = cm.copy()    np.fill_diagonal(cm_off_diagonal, 0)    max_confusion_idx = np.unravel_index(np.argmax(cm_off_diagonal), cm_off_diagonal.shape)    most_confused_pair = (cluster_names[max_confusion_idx[0]], cluster_names[max_confusion_idx[1]])    max_confusion_count = cm_off_diagonal[max_confusion_idx]        # Count perfectly classified clusters (100% recall)    perfect_clusters = sum(1 for recall in cluster_recalls.values() if recall == 1.0)        # Count poorly classified clusters (< 50% recall)    poor_clusters = sum(1 for recall in cluster_recalls.values() if recall < 0.5)        results = {        'confusion_matrix': cm_df,        'overall_accuracy': overall_accuracy,        'mean_cluster_recall': mean_cluster_recall,        'mean_cluster_precision': mean_cluster_precision,        'cluster_recalls': cluster_recalls,        'cluster_precisions': cluster_precisions,        'perfect_clusters': perfect_clusters,        'poor_clusters': poor_clusters,        'most_confused_pair': most_confused_pair,        'max_confusion_count': max_confusion_count,        'n_clusters': len(cluster_names),        'n_genes': len(gene_set)    }        return results# Example usage:cm_results = validate_confusion_matrix(expression_binary, clusters['clusters'], genes_nonredundant_minimal)# print(f"Overall Accuracy: {cm_results['overall_accuracy']:.3f}")print(f"Mean Cluster Recall: {cm_results['mean_cluster_recall']:.3f}")print(f"Perfect Clusters: {cm_results['perfect_clusters']}/{cm_results['n_clusters']}")print(f"Poor Clusters: {cm_results['poor_clusters']}/{cm_results['n_clusters']}")print(f"Most confused pair: {cm_results['most_confused_pair']} ({cm_results['max_confusion_count']} misclassifications)")def validate_information_capture(expression_binary, cluster_labels, gene_set):    """    Validate how much cluster information is captured by the gene set    using information theory metrics        Parameters:    -----------    expression_binary : DataFrame        Binarized gene expression matrix (genes as rows, cells as columns)    cluster_labels : Series or array        Cluster labels for each cell    gene_set : list        List of gene names to use for validation            Returns:    --------    dict : Dictionary containing information theory metrics    """    from scipy.stats import entropy    import numpy as np    import pandas as pd        # Calculate baseline entropy (maximum possible information)    cluster_counts = pd.Series(cluster_labels).value_counts(normalize=True)    H_clusters = entropy(cluster_counts, base=2)        # Get expression data for selected genes    gene_expression = expression_binary.loc[gene_set].T  # Cells as rows, genes as columns        # Ensure cluster_labels is aligned with gene_expression index    cluster_labels_series = pd.Series(cluster_labels, index=gene_expression.index)        # Calculate conditional entropy H(Clusters | Gene Expression)    H_conditional = 0    total_cells = len(cluster_labels_series)        # Group cells by their gene expression patterns    expression_patterns = gene_expression.drop_duplicates()        for _, pattern in expression_patterns.iterrows():        # Find cells with this expression pattern        matching_cells = np.all(gene_expression == pattern, axis=1)        n_matching = np.sum(matching_cells)                if n_matching > 0:            # Get cluster labels for cells with this pattern            pattern_clusters = cluster_labels_series[matching_cells]            pattern_cluster_counts = pattern_clusters.value_counts(normalize=True)                        # Calculate entropy for this pattern            if len(pattern_cluster_counts) > 1:                H_pattern = entropy(pattern_cluster_counts, base=2)            else:                H_pattern = 0  # Perfect classification for this pattern                        # Weight by proportion of cells with this pattern            weight = n_matching / total_cells            H_conditional += weight * H_pattern        # Calculate mutual information    mutual_info = H_clusters - H_conditional        # Calculate information capture ratio    info_capture_ratio = mutual_info / H_clusters if H_clusters > 0 else 0        # Calculate number of unique expression patterns    n_patterns = len(expression_patterns)    max_possible_patterns = 2 ** len(gene_set)  # 2^n for binary genes    pattern_efficiency = n_patterns / max_possible_patterns        # Calculate pattern purity (how many patterns lead to single cluster)    pure_patterns = 0    impure_patterns = 0    pattern_purities = []        for _, pattern in expression_patterns.iterrows():        matching_cells = np.all(gene_expression == pattern, axis=1)        pattern_clusters = cluster_labels_series[matching_cells]        unique_clusters = len(pattern_clusters.unique())                if unique_clusters == 1:            pure_patterns += 1            pattern_purities.append(1.0)        else:            impure_patterns += 1            # Calculate purity as fraction of most common cluster            most_common_fraction = pattern_clusters.value_counts().max() / len(pattern_clusters)            pattern_purities.append(most_common_fraction)        mean_pattern_purity = np.mean(pattern_purities) if pattern_purities else 0        # Calculate redundancy (how many cells share the same pattern)    pattern_sizes = []    for _, pattern in expression_patterns.iterrows():        matching_cells = np.all(gene_expression == pattern, axis=1)        pattern_sizes.append(np.sum(matching_cells))        mean_pattern_size = np.mean(pattern_sizes)    max_pattern_size = np.max(pattern_sizes)        results = {        'baseline_entropy': H_clusters,        'conditional_entropy': H_conditional,        'mutual_information': mutual_info,        'info_capture_ratio': info_capture_ratio,        'n_unique_patterns': n_patterns,        'max_possible_patterns': max_possible_patterns,        'pattern_efficiency': pattern_efficiency,        'pure_patterns': pure_patterns,        'impure_patterns': impure_patterns,        'fraction_pure_patterns': pure_patterns / n_patterns if n_patterns > 0 else 0,        'mean_pattern_purity': mean_pattern_purity,        'mean_pattern_size': mean_pattern_size,        'max_pattern_size': max_pattern_size,        'n_genes': len(gene_set),        'n_clusters': len(cluster_counts)    }        return results# Example usage:info_results = validate_information_capture(    expression_binary,     clusters['clusters'],     genes_nonredundant_minimal)print(f"Information Capture Ratio: {info_results['info_capture_ratio']:.3f}")print(f"Mutual Information: {info_results['mutual_information']:.3f} bits")print(f"Baseline Entropy: {info_results['baseline_entropy']:.3f} bits")print(f"Pure Expression Patterns: {info_results['pure_patterns']}/{info_results['n_unique_patterns']} ({info_results['fraction_pure_patterns']:.2f})")print(f"Mean Pattern Purity: {info_results['mean_pattern_purity']:.3f}")#### claude is fucking stupid and doesnt know how to write code I am just going to do 120 from FindAllMarkers and see what hte fuck that gives me# fucking stupid asshole